package com.portfolio.controller; import com.portfolio.model.Skill; import com.portfolio.repository.SkillRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/skills") public class SkillController {final SkillRepository repo; SkillController(SkillRepository r){repo=r;} @GetMapping public List<Skill> all(){return repo.findAll();} @PostMapping public Skill create(@RequestBody Skill s){return repo.save(s);} @PutMapping("/{id}") public Skill update(@PathVariable Long id,@RequestBody Skill s){s.id=id;return repo.save(s);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
